package com.gymmind.booking.application; import com.gymmind.audit.application.AuditRecorder; import com.gymmind.booking.domain.model.*; import com.gymmind.booking.domain.repository.BookingRepository; import com.gymmind.course.domain.model.Course; import com.gymmind.course.domain.repository.CourseRepository; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.shared.security.CurrentActor; import org.junit.jupiter.api.Test; import java.time.Instant; import java.util.Optional; import java.util.Set; import static org.assertj.core.api.Assertions.assertThatThrownBy; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class BookingServiceTest{@Test void bookingIsTenantScopedAndCapacityChecked(){CourseRepository courses=mock(CourseRepository.class);BookingRepository bookings=mock(BookingRepository.class);Course c=Course.create(11L,3L,"Yoga","GROUP",Instant.now().plusSeconds(3600),Instant.now().plusSeconds(7200),1,"Studio");when(courses.findByTenantIdAndId(11L,4L)).thenReturn(Optional.of(c));when(bookings.findByTenantIdAndMemberIdAndCourseId(11L,41L,4L)).thenReturn(Optional.empty());when(bookings.save(any(Booking.class))).thenAnswer(i->i.getArgument(0));BookingService service=new DefaultBookingService(courses,bookings,mock(AuditRecorder.class));service.book(admin(11L),new BookCourseCommand(null,41L,4L));assertThatThrownBy(()->service.book(admin(11L),new BookCourseCommand(null,42L,4L))).isInstanceOf(com.gymmind.shared.error.BusinessException.class);}private static CurrentActor admin(long t){return new CurrentActor(1L,t,Set.of(RoleCode.GYM_ADMIN),Set.of("booking:write"),0L,"token");}}
